<?php
declare(strict_types=1);
/** Integration tests. ONLY run against a disposable DB whose name ends in _test. */
if (PHP_SAPI !== 'cli') { http_response_code(404); exit; }
require dirname(__DIR__).'/app/bootstrap.php';
use KB\{DB,Settings,Security,Auth,Quiz,Mail,Activation,Audit,Cron,MailError,Google};
use function KB\{hash_password,valid_password,now};
if (!KB\installed() || !str_ends_with((string)KB\config('db')['name'],'_test') || !KB\config('local_preview',false)) {
    fwrite(STDERR,"Refusing to run: use an installed, local-preview configuration with a *_test database.\n"); exit(1);
}
$pdo=DB::connection();
$pdo->exec('SET FOREIGN_KEY_CHECKS=0');
foreach (['attempt_items','attempts','access_tokens','mail_queue','audit_events','rate_limits','questions','users','settings'] as $table) $pdo->exec('DELETE FROM '.$table);
$pdo->exec('SET FOREIGN_KEY_CHECKS=1');
$pass=0;$fail=0;
function test(string $name,callable $fn): void {
    global $pass,$fail;
    try {$fn();echo "PASS {$name}\n";$pass++;}
    catch(Throwable $e){echo "FAIL {$name}: ".$e->getMessage()."\n";$fail++;}
}
function assert_true(bool $condition,string $message='Assertion failed'): void {if(!$condition)throw new RuntimeException($message);}
function rejects(callable $fn,int $status=0): void {
    try{$fn();}catch(KB\UserError $e){if($status && $e->status!==$status)throw new RuntimeException('Unexpected status '.$e->status);return;}
    throw new RuntimeException('Expected request to be rejected');
}
$hash=hash_password('Correct-Horse-Battery-Staple!');
$makeUser=static function(string $email,string $role='member') use($hash):int {
    DB::run('INSERT INTO users(name,email,password_hash,role,status,email_verified_at,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?)',['Test '.ucfirst($role),$email,$hash,$role,'active',now(),now(),now()]);return DB::id();
};
putenv('KB_PREVIEW_ACTIVATION=local-fixture');
$admin=$makeUser('admin@example.test','admin');$member=$makeUser('member@example.test');$other=$makeUser('other@example.test');
foreach(Settings::DEFAULTS as $key=>$value)Settings::put($key,$value);
Settings::put('admin_email','admin@example.test');Settings::put('questions_per_attempt',3);Settings::put('seconds_per_question',30);Settings::put('max_tab_switches',0);
$insert=$pdo->prepare('INSERT INTO questions(category,question_text,option_a,option_b,option_c,option_d,correct_option,reference,explanation,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?)');
for($i=0;$i<8;$i++)$insert->execute(['Test','Question '.$i.' — choose the correct option.','A','B','C','D',$i%4,'Reference','',now(),now()]);

test('Password hashing and length boundaries',function()use($hash){assert_true(password_verify('Correct-Horse-Battery-Staple!',$hash));assert_true(!password_verify('wrong',$hash));assert_true(valid_password(str_repeat('a',72)));assert_true(!valid_password(str_repeat('a',73)));});
test('Authenticated encryption and tamper rejection',function(){$sealed=Security::seal(['secret'=>'never-public']);assert_true(Security::unseal($sealed)['secret']==='never-public');assert_true(!str_contains($sealed,'never-public'));$raw=base64_decode(substr($sealed,4));$raw[30]=chr(ord($raw[30])^1);$reject=false;try{Security::unseal('KB1:'.base64_encode($raw));}catch(Throwable $e){$reject=true;}assert_true($reject);});
test('Canonical site address validation',function(){assert_true(Security::canonicalUrl('https://example.org/path')==='https://example.org/path');assert_true(Security::canonicalUrl('https://user:pass@example.org')===null);assert_true(Security::canonicalUrl('javascript:alert(1)')===null);});
test('First Unicode character favicon source',function(){Settings::put('site_title','Ẹ̀kọ́ Bible');assert_true(KB\initial()==='Ẹ');Settings::put('site_title','KINGDOMBUILDERS');});
test('Quiz snapshots omit no server answer key in public payload',function()use($member){$id=Quiz::start($member);$state=Quiz::payload($id,$member);assert_true($state['total']===3);assert_true(count($state['questions'])===3);foreach($state['questions'] as $q){assert_true(!isset($q['correct_option'])&&!isset($q['correct'])&&!isset($q['explanation']));}});
test('Concurrent starts return one active attempt',function()use($member){$before=DB::one('SELECT id FROM attempts WHERE active_user_id=?',[$member]);$again=Quiz::start($member);assert_true($before['id']===$again);assert_true((int)DB::value('SELECT COUNT(*) FROM attempts WHERE active_user_id=?',[$member])===1);});
test('Forward-only answers and ownership enforced',function()use($member,$other){$id=Quiz::start($member);rejects(fn()=>Quiz::answer($id,$member,1,0),409);rejects(fn()=>Quiz::payload($id,$other),404);Quiz::answer($id,$member,0,0);rejects(fn()=>Quiz::answer($id,$member,0,1),409);});
test('Question edits preserve active-attempt snapshots',function()use($member){$id=Quiz::start($member);$before=Quiz::payload($id,$member)['questions'][0]['question'];$item=DB::one('SELECT question_id FROM attempt_items WHERE attempt_id=? AND position=0',[$id]);DB::run('UPDATE questions SET question_text="Changed after start" WHERE id=?',[$item['question_id']]);assert_true(Quiz::payload($id,$member)['questions'][0]['question']===$before);});
test('Scoring correct, idempotent, one result email',function()use($member,$makeUser){$scorer=$makeUser('scorer@example.test');$id=Quiz::start($scorer);$keys=DB::all('SELECT position,correct_option FROM attempt_items WHERE attempt_id=? ORDER BY position',[$id]);foreach($keys as $q)Quiz::answer($id,$scorer,(int)$q['position'],(int)$q['correct_option']);$a=Quiz::finish($id,$scorer);$b=Quiz::finish($id,$scorer);assert_true($a['score']===3 && $a['percentage']==100.0);assert_true($b['score']===3);assert_true((int)DB::value('SELECT COUNT(*) FROM mail_queue WHERE idempotency_key LIKE ?',["assessment.completed:attempt:{$id}%"])===1);});
test('Expired deadline cannot accept answers',function()use($other){$id=Quiz::start($other);DB::run('UPDATE attempts SET expires_at=? WHERE id=?',[gmdate('Y-m-d H:i:s',time()-1),$id]);rejects(fn()=>Quiz::answer($id,$other,0,0),409);assert_true(Quiz::payload($id,$other)['status']==='expired');});
test('Focus threshold finalizes server-side',function()use($other,$makeUser){$focus=$makeUser('focus@example.test');Settings::put('max_tab_switches',1);$id=Quiz::start($focus);$flag=Quiz::flag($id,$focus);assert_true($flag['ended']);assert_true(Quiz::payload($id,$focus)['status']==='submitted');Settings::put('max_tab_switches',0);});
test('Single-use reset token and session revocation',function()use($member){$token=Auth::issueToken($member,'reset');$hash=hash('sha256',$token);$row=DB::one('SELECT * FROM access_tokens WHERE token_hash=?',[$hash]);assert_true($row['token_hash']!==$token);assert_true(DB::run('UPDATE access_tokens SET used_at=? WHERE id=? AND used_at IS NULL',[now(),$row['id']])->rowCount()===1);assert_true(DB::run('UPDATE access_tokens SET used_at=? WHERE id=? AND used_at IS NULL',[now(),$row['id']])->rowCount()===0);Auth::revoke($member);assert_true((int)DB::value('SELECT session_version FROM users WHERE id=?',[$member])===2);});
test('Suspension revokes existing session identity',function()use($other){$user=DB::one('SELECT * FROM users WHERE id=?',[$other]);$_SESSION=[];Auth::signIn($user,false);assert_true(Auth::id()===$other);DB::run('UPDATE users SET status="suspended",session_version=session_version+1 WHERE id=?',[$other]);(new ReflectionClass(Auth::class))->setStaticPropertyValue('loaded',false);assert_true(Auth::user()===null);DB::run('UPDATE users SET status="active" WHERE id=?',[$other]);});
test('Duplicate notification idempotency',function(){Mail::queue('member@example.test','Test','Body','test:unique');Mail::queue('member@example.test','Test','Body','test:unique');assert_true((int)DB::value('SELECT COUNT(*) FROM mail_queue WHERE idempotency_key="test:unique"')===1);});
test('SMTP test reports safe diagnostics instead of failing silently',function(){Settings::put('smtp_enabled',false);$thrown=null;try{Mail::sendTest('recipient@example.test');}catch(MailError $e){$thrown=$e;}assert_true($thrown instanceof MailError,'Expected MailError');assert_true($thrown->stage==='configuration');assert_true(!str_contains($thrown->getMessage(),'secret'));Settings::put('smtp_enabled',true);Settings::put('smtp_host','127.0.0.1');Settings::put('smtp_port',1);Settings::put('smtp_security','none');Settings::put('from_email','notifications@example.test');Settings::put('from_name','Test');$connection=null;try{Mail::sendTest('recipient@example.test');}catch(MailError $e){$connection=$e;}assert_true($connection instanceof MailError,'Expected connection MailError');assert_true($connection->stage==='connection','Unexpected stage '.$connection->stage);assert_true($connection->retryable===true,'Temporary connection failures remain retryable');Settings::put('smtp_enabled',false);});
test('SMTP validation accepts real hosts and rejects junk',function(){$base=array_merge(Settings::all(),['smtp_enabled'=>true,'smtp_host'=>'mail.example.com','smtp_port'=>587,'smtp_security'=>'tls','from_email'=>'notifications@example.com','from_name'=>'Test','php_cli_path'=>'']);assert_true(Settings::validate($base,true)['smtp_host']==='mail.example.com');foreach(['https://mail.example.com','mail.example.com:587','bad host','-bad.example.com'] as $host){$bad=$base;$bad['smtp_host']=$host;rejects(fn()=>Settings::validate($bad,true));} $bad=$base;$bad['php_cli_path']='../../etc/passwd';rejects(fn()=>Settings::validate($bad,true));assert_true(Settings::validate(array_merge($base,['php_cli_path'=>'/usr/local/bin/php']),true)['php_cli_path']==='/usr/local/bin/php');});
test('Saving settings is not needed for a test run',function(){Settings::put('smtp_host','saved.example.com');Settings::preview(['smtp_host'=>'temporary.example.com']);assert_true(Settings::get('smtp_host')==='temporary.example.com');Settings::flushCache();assert_true(Settings::get('smtp_host')==='saved.example.com');});
test('Queue processing reports remaining messages without cron',function(){Settings::put('smtp_enabled',false);DB::run('DELETE FROM mail_queue');Mail::queue('member@example.test','Queued','Body','test:queued:'.bin2hex(random_bytes(4)));$stats=Mail::process(1);assert_true($stats['sent']===0&&$stats['failed']===0);assert_true($stats['pending']===1,'Expected one pending message');Settings::put('smtp_enabled',true);Settings::put('smtp_host','127.0.0.1');Settings::put('smtp_port',1);Settings::put('smtp_security','none');Settings::put('from_email','notifications@example.test');Settings::put('from_name','Test');$bounded=Mail::process(5,time()-1);assert_true($bounded['processed']===0,'Expired deadline must stop delivery');Settings::put('smtp_enabled',false);DB::run('DELETE FROM mail_queue');});
test('A queued message can be delivered on demand with a real diagnosis',function(){Settings::put('smtp_enabled',false);DB::run('DELETE FROM mail_queue');Mail::queue('member@example.test','On demand','Body','test:deliver:'.bin2hex(random_bytes(4)));$id=(int)DB::value('SELECT MAX(id) FROM mail_queue');$disabled=Mail::deliver($id);assert_true($disabled['ok']===false&&str_contains($disabled['message'],'disabled'));Settings::put('smtp_enabled',true);Settings::put('smtp_host','127.0.0.1');Settings::put('smtp_port',1);Settings::put('smtp_security','none');Settings::put('from_email','notifications@example.test');Settings::put('from_name','Test');$failed=Mail::deliver($id);assert_true($failed['ok']===false&&str_contains($failed['message'],'Could not connect'));$row=DB::one('SELECT status,last_error FROM mail_queue WHERE id=?',[$id]);assert_true($row['status']==='failed'&&$row['last_error']!==null);Settings::put('smtp_enabled',false);DB::run('DELETE FROM mail_queue');});
test('Extra-large text is an administrator setting',function(){assert_true(Settings::DEFAULTS['large_text']===false);$values=Settings::validate(array_merge(Settings::all(),['site_title'=>'KINGDOMBUILDERS','admin_email'=>'admin@example.test','large_text'=>'1']));assert_true($values['large_text']===true);$values=Settings::validate(array_merge(Settings::all(),['site_title'=>'KINGDOMBUILDERS','admin_email'=>'admin@example.test']));assert_true($values['large_text']===false);});
test('Cron instructions are copy-safe and include private configuration',function(){$info=Cron::info();assert_true(str_contains($info['crontab'],'* * * * *'));assert_true(str_contains($info['crontab'],'bin/worker.php'));assert_true(str_contains($info['crontab'],'KB_CONFIG_DIR='));assert_true(!str_contains($info['crontab'],"\n")&&!str_contains($info['crontab'],"\r"));Cron::record(['ok'=>true,'sent'=>2,'failed'=>0]);assert_true((Cron::heartbeat()['sent']??null)===2);});
test('Audit accepts string identifiers from PDO/MySQL',function()use($member){Audit::log('test.string_actor','user',$member,[],(string)$member);Audit::activity('test.string_activity','user',$member,[],['id'=>(string)$member,'name'=>'String ID','email'=>'member@example.test'],'String identifier regression');$row=DB::one('SELECT actor_id FROM audit_events WHERE action="test.string_actor" ORDER BY id DESC LIMIT 1');assert_true((int)$row['actor_id']===$member);});
test('Nested transaction rolls back audit and outbox together',function(){$before=(int)DB::value('SELECT COUNT(*) FROM audit_events');try{DB::transaction(static function(){Audit::activity('test.rollback','site',999);throw new RuntimeException('rollback');});}catch(RuntimeException $e){}assert_true((int)DB::value('SELECT COUNT(*) FROM audit_events')===$before);});
test('Atomic fixed-window rate limiter',function(){for($i=0;$i<3;$i++)Security::throttle('test','identity',3,60);rejects(fn()=>Security::throttle('test','identity',3,60),429);});
test('Local authorization fixture is explicit and domain state encrypted',function(){assert_true(Activation::verify('LOCAL-PREVIEW-ONLY','example.test'));assert_true(!Activation::verify('','example.test'));Activation::save('LOCAL-PREVIEW-ONLY',true);assert_true(Activation::allowed());assert_true(!str_contains(file_get_contents(KB\config_path().'/runtime.dat'),'LOCAL-PREVIEW-ONLY'));});
test('Google sign-in is off until an administrator configures it',function(){foreach(['google_enabled'=>false,'google_client_id'=>'','google_client_secret'=>''] as $k=>$v)Settings::put($k,$v);assert_true(!Google::enabled());assert_true(!Google::configured());rejects(fn()=>Google::begin('login'),404);});
test('Google authorization request carries state, PKCE and exact redirect',function(){Settings::put('google_client_id','123-abc.apps.googleusercontent.com');Settings::put('google_enabled',true);$pkce=Google::pkce();assert_true(strlen($pkce['verifier'])>=43&&strlen($pkce['verifier'])<=128);assert_true(Google::challenge($pkce['verifier'])===$pkce['challenge']);assert_true(!str_contains($pkce['challenge'],'='));$url=Google::authorizationUrl('STATE-123',$pkce['challenge'],'NONCE-123');parse_str((string)parse_url($url,PHP_URL_QUERY),$q);assert_true(str_starts_with($url,'https://accounts.google.com/'),'Unexpected endpoint');assert_true(($q['client_id']??'')==='123-abc.apps.googleusercontent.com');assert_true(($q['redirect_uri']??'')===rtrim((string)KB\config('site_url'),'/').'/auth/google/callback');assert_true(($q['state']??'')==='STATE-123'&&($q['nonce']??'')==='NONCE-123');assert_true(($q['code_challenge_method']??'')==='S256');assert_true(($q['code_challenge']??'')===$pkce['challenge']);assert_true(str_contains((string)($q['scope']??''),'email')&&str_contains((string)($q['scope']??''),'openid'));});
test('Google sign-in stores one-time state and rejects forged or expired callbacks',function(){Settings::put('google_client_id','123-abc.apps.googleusercontent.com');Settings::put('google_enabled',true);Settings::put('google_client_secret',Security::seal(['value'=>'test-client-secret']));$_SESSION=[];$url=Google::begin('register');$state=$_SESSION['google_oauth']['state']??'';assert_true($state!==''&&str_contains($url,'state='.rawurlencode($state)));assert_true(($_SESSION['google_oauth']['from']??'')==='register');rejects(fn()=>Google::complete('code','not-the-state'),400);assert_true(!isset($_SESSION['google_oauth']),'State must be single use');$_SESSION['google_oauth']=['state'=>'good','verifier'=>'verifier-value','nonce'=>'nonce-value','started'=>time()-1000];rejects(fn()=>Google::complete('code','good'),400);$_SESSION=[];rejects(fn()=>Google::complete('code','good'),400);});
test('Google links verified emails, creates members and honours suspension',function(){Settings::put('google_client_id','123-abc.apps.googleusercontent.com');Settings::put('google_enabled',true);Settings::put('registration_open',true);$email='google-new@example.test';DB::run('DELETE FROM users WHERE email=?',[$email]);$profile=['email'=>$email,'name'=>'Grace Example','email_verified'=>true,'sub'=>'google-sub-1'];$user=Google::accountFor($profile);assert_true($user['role']==='member'&&$user['status']==='active');assert_true(!empty($user['email_verified_at']));$again=Google::accountFor($profile);assert_true((int)$again['id']===(int)$user['id']);assert_true((int)DB::value('SELECT COUNT(*) FROM users WHERE email=?',[$email])===1);rejects(fn()=>Google::accountFor(['email'=>'unverified-google@example.test','name'=>'No','email_verified'=>false]),403);DB::run('UPDATE users SET status="suspended" WHERE id=?',[$user['id']]);rejects(fn()=>Google::accountFor($profile),403);DB::run('DELETE FROM users WHERE id=?',[$user['id']]);});
test('Google proves ownership of an existing unverified account',function(){Settings::put('google_client_id','123-abc.apps.googleusercontent.com');Settings::put('google_enabled',true);$email='google-unverified@example.test';DB::run('DELETE FROM users WHERE email=?',[$email]);DB::run('INSERT INTO users(name,email,password_hash,email_verified_at,created_at,updated_at) VALUES (?,?,?,?,?,?)',['Pending Member',$email,hash_password('Correct-Horse-Battery-Staple!'),null,now(),now()]);$id=(int)DB::value('SELECT id FROM users WHERE email=?',[$email]);$user=Google::accountFor(['email'=>$email,'name'=>'Pending Member','email_verified'=>true,'sub'=>'google-sub-2']);assert_true((int)$user['id']===$id);assert_true(!empty(DB::value('SELECT email_verified_at FROM users WHERE id=?',[$id])));DB::run('DELETE FROM users WHERE id=?',[$id]);});
test('Google respects closed registration for new accounts only',function(){Settings::put('google_client_id','123-abc.apps.googleusercontent.com');Settings::put('google_enabled',true);Settings::put('registration_open',false);rejects(fn()=>Google::accountFor(['email'=>'closed-registration@example.test','email_verified'=>true]),403);assert_true(Google::accountFor(['email'=>'member@example.test','email_verified'=>true])['id']===(int)DB::value('SELECT id FROM users WHERE email=?',['member@example.test']));Settings::put('registration_open',true);});
test('Google settings require a client id and never expose the secret',function(){$base=array_merge(Settings::all(),['site_title'=>'KINGDOMBUILDERS','admin_email'=>'admin@example.test','google_enabled'=>'1','google_client_id'=>'123-abc.apps.googleusercontent.com']);$values=Settings::validate($base);assert_true($values['google_client_id']==='123-abc.apps.googleusercontent.com');assert_true($values['google_enabled']===true);assert_true(!array_key_exists('google_client_secret',$values),'Secret must never be copied into validated settings');rejects(fn()=>Settings::validate(array_merge($base,['google_client_id'=>''])));rejects(fn()=>Settings::validate(array_merge($base,['google_client_id'=>'https://not a client id'])));$disabled=Settings::validate(array_merge($base,['google_enabled'=>'0','google_client_id'=>'']));assert_true($disabled['google_enabled']===false);});
